import re
training = ["Learn AI with Python", "Build useful AI tools"]
def tokenize(text):
    return re.findall(r"[a-z]+", text.casefold())
words = sorted({word for text in training for word in tokenize(text)})
vocabulary = {word: i+1 for i, word in enumerate(words)}
encoded = [vocabulary.get(word, 0) for word in tokenize("Learn new tools")]
print("Vocabulary:", vocabulary)
print("Token IDs:", encoded)
